import Foundation

/// The bundled patient strings. Resources are generated by ios/Tools/sync-strings.py from the
/// website's dictionaries, so nothing here is written by hand.
public struct Strings: Sendable {
    public typealias Vars = [String: any CustomStringConvertible & Sendable]

    let dictionaries: [Lang: [String: String]]
    let recordTerms: [String: String]

    public init(en: [String: String], ar: [String: String], recordTerms: [String: String] = [:]) {
        self.dictionaries = [.en: en, .ar: ar]
        self.recordTerms = recordTerms
    }

    /// The package's own resources, so a failure here is a broken build, not a runtime case.
    public static let bundled: Strings = {
        func table(_ name: String) -> [String: String] {
            guard let url = Bundle.module.url(forResource: name, withExtension: "json"),
                  let data = try? Data(contentsOf: url),
                  let table = try? JSONDecoder().decode([String: String].self, from: data)
            else { preconditionFailure("Missing or invalid bundled resource \(name).json") }
            return table
        }
        return Strings(
            en: table("strings.en"), ar: table("strings.ar"), recordTerms: table("record.ar"))
    }()

    /// `translate()` in frontend/src/i18n/index.tsx: a missing key comes back as the key,
    /// `{name}` placeholders are filled, and an unknown placeholder stays as written.
    public func translate(_ lang: Lang, _ key: String, _ vars: Vars? = nil) -> String {
        guard let text = dictionaries[lang]?[key] else { return key }
        guard let vars else { return text }
        // Scalar semantics: an Arabic mark straight after `}` must not hide the brace.
        let placeholder = #/\{([A-Za-z0-9_]+)\}/#.matchingSemantics(.unicodeScalar)
        return text.replacing(placeholder) { match in
            vars[String(match.output.1)].map(\.description) ?? String(match.output.0)
        }
    }

    /// `recordTerm` in frontend/src/i18n/record.ts. Unknown values come back as stored:
    /// never guess a clinical term.
    public func recordTerm(_ value: String, lang: Lang) -> String {
        guard lang == .ar else { return value }
        let key = value.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        return recordTerms[key] ?? value
    }
}
